/// Application error type
#[derive(Debug, thiserror::Error)]
pub enum SmsError {
    #[error("Not found: {0}")]
    NotFound(String),
    #[error("Validation error: {0}")]
    Validation(String),
    #[error("Database error: {0}")]
    Database(String),
    #[error("Internal error: {0}")]
    Internal(String),
    // Domain-specific errors from hook rules
    #[error("sms.sms _uuid_unique — the uuid is the IAP correlation key and the tracker's link target; duplicates are rejected (fires on raw SQL in v19). Enforced by @unique on Sms.uuid.: {0}")]
    SmsUuidDuplicate(String),
}

impl From<ServiceError> for SmsError {
    fn from(err: ServiceError) -> Self {
        match err {
            ServiceError::NotFound => Self::NotFound(err.to_string()),
            ServiceError::Validation(ref msg) => Self::Validation(msg.clone()),
            ServiceError::AlreadyExists(ref msg) => Self::Validation(msg.clone()),
            ServiceError::Repository(ref e) => Self::Database(e.to_string()),
            ServiceError::Internal(ref msg) => Self::Internal(msg.clone()),
        }
    }
}

impl axum::response::IntoResponse for SmsError {
    fn into_response(self) -> axum::response::Response {
        use axum::http::StatusCode;
        use axum::Json;

        let (status, code) = match &self {
            Self::NotFound(_) => (StatusCode::NOT_FOUND, "SMS_NOT_FOUND"),
            Self::Validation(_) => (StatusCode::BAD_REQUEST, "SMS_VALIDATION_ERROR"),
            Self::Database(_) => (StatusCode::INTERNAL_SERVER_ERROR, "SMS_DATABASE_ERROR"),
            Self::Internal(_) => (StatusCode::INTERNAL_SERVER_ERROR, "SMS_INTERNAL_ERROR"),
            Self::SmsUuidDuplicate(_) => (StatusCode::UNPROCESSABLE_ENTITY, "SMS_SMS_UUID_DUPLICATE"),
        };

        let body = serde_json::json!({
            "success": false,
            "error": code,
            "message": self.to_string(),
        });

        (status, Json(body)).into_response()
    }
}

