/// Execute pickup transition on a Sms.
///
/// POST /smses/:id/transitions/pickup
pub async fn pickup_transition(
    axum::extract::State(service): axum::extract::State<Arc<SmsService>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    #[cfg(feature = "auth")] axum::Extension(auth): axum::Extension<AuthContext>,
) -> impl axum::response::IntoResponse {
    use axum::{http::StatusCode, Json};

    // Get current entity
    let entity = match service.get_by_id(&id).await {
        Ok(Some(e)) => e,
        Ok(None) => return (StatusCode::NOT_FOUND, Json(ApiResponse::<SmsResponseDto>::not_found("Sms", &id))),
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, Json(ApiResponse::<SmsResponseDto>::error(e.to_string()))),
    };

    // Check permission (if auth enabled)
    #[cfg(feature = "auth")]
    {
        let allowed_roles = SmsTransition::Pickup.allowed_roles();
        let has_specific_perm = auth.permissions.iter().any(|p| p == "sms:transition:pickup");
        let has_update_perm = auth.permissions.iter().any(|p| p == "sms:update");
        if !has_specific_perm && !has_update_perm {
            return (StatusCode::FORBIDDEN, Json(ApiResponse::<SmsResponseDto>::error("Insufficient permissions for pickup transition")));
        }
    }

    // Create state machine from entity's actual status and validate transition
    let current_state: SmsState = entity.state.to_string().parse()
        .unwrap_or(SmsState::default());
    let sm = SmsStateMachine::from_state(current_state);
    if !sm.can_transition(SmsTransition::Pickup) {
        return (StatusCode::BAD_REQUEST, Json(ApiResponse::<SmsResponseDto>::error("Transition not allowed from current state")));
    }

    // Apply transition via partial update
    let mut fields: HashMap<String, serde_json::Value> = HashMap::new();
    fields.insert("state".to_string(), serde_json::Value::String("Process".to_string()));

    match service.partial_update(&id, fields).await {
        Ok(Some(updated)) => {
            let response: SmsResponseDto = updated.into();
            (StatusCode::OK, Json(ApiResponse::ok(response)))
        }
        Ok(None) => (StatusCode::NOT_FOUND, Json(ApiResponse::<SmsResponseDto>::not_found("Sms", &id))),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, Json(ApiResponse::<SmsResponseDto>::error(e.to_string()))),
    }
}

